-- ===========================================================================
--  De takenmail: om 7 en om 15 uur wat er bij je ligt
--
--  Casper: "zorg ook ervoor dat iedereen om 7 uur en 15:00 uur een mail
--  krijgen met al hun todo's".
--
--  Waarom de lijst hier wordt gemaakt en niet in de serverfunctie
--  --------------------------------------------------------------
--
--  "Wat ligt er bij mij" is niet één kolom. Het is: alles wat op mijn naam
--  staat, plus alles wat bij mijn rol ligt op een vestiging waar ik bij mag --
--  want dat tweede is werk dat nog door niemand is opgepakt, en juist dat
--  hoort in een ochtendmail te staan.
--
--  Dat is dezelfde regel als isVanMij() in de app en als de policy op taak in
--  0067. Die drie horen hetzelfde te zeggen. Door hem hier neer te zetten
--  hoeft de serverfunctie niets van rollen, vestigingen of manages[] te weten
--  en kan hij niet stilletjes uit de pas gaan lopen.
--
--  Wie krijgt er een mail
--  ----------------------
--
--  Iedereen die iets open heeft staan. Niet "alle leidinggevenden": wie niets
--  te doen heeft krijgt niets, want een mail die drie keer per week leeg is,
--  is een mail die je na twee weken niet meer opent.
--
--  Uitgeschreven mensen en mensen zonder e-mailadres vallen af. Dat laatste
--  komt voor: een dossier kan bestaan zonder inlogaccount.
--
--  Opnieuw draaien mag.
-- ===========================================================================

-- ---------------------------------------------------------------------------
--  De uren waarop hij gaat
--
--  Als instelling en niet als vaste waarde: de serverfunctie draait elk uur
--  langs en kijkt hier of het zover is. Zeven en vijftien nu; wil Casper er
--  een derde bij, dan is dat een regel in dit veld en geen nieuwe versie.
-- ---------------------------------------------------------------------------

insert into public.instellingen (id, sleutel, waarde, omschrijving) values
  ('in_taken_mail_uren', 'taken_mail_uren', '7,15',
   'Op welke hele uren (Nederlandse tijd) de takenmail wordt verstuurd. '
   'Komma''s ertussen. Leeg laten zet hem uit.')
on conflict (id) do nothing;

-- ---------------------------------------------------------------------------
--  Wat er bij wie ligt
--
--  Eén rij per persoon die iets open heeft staan, met zijn taken als jsonb.
--  De serverfunctie hoeft er alleen nog een mail van te maken.
-- ---------------------------------------------------------------------------

drop function if exists public.taken_voor_mail();

create function public.taken_voor_mail()
returns table (
  profile_id text,
  naam       text,
  email      text,
  aantal     integer,
  te_laat    integer,
  taken      jsonb
)
language sql stable security definer set search_path = public as $$
  with mens as (
    select p.id, p.name, p.email,
           coalesce(p.roles, array[]::text[]) as roles,
           coalesce(p.all_locations, false)   as overal,
           /* Zijn eigen vestiging plus de vestigingen waar hij leiding over
              heeft -- dezelfde optelsom als my_locations(), maar dan voor een
              wíllekeurige persoon en niet voor de beller. */
           array_remove(
             coalesce(p.manages, array[]::text[]) || coalesce(p.location_id, ''),
             ''
           ) as locaties
      from public.profiles p
     where p.active
       and coalesce(p.email, '') <> ''
       /* Uitgeschreven staat als archived_at op het dossier; zie 0023. */
       and p.archived_at is null
  ),
  paren as (
    /* Kolom voor kolom en niet t.*: de taak heeft ook een id, en dan is "id"
       verderop dubbelzinnig -- Postgres weigert de query en zegt precies dat. */
    select m.id as wie, m.name as wie_naam, m.email as wie_mail,
           t.titel, t.prioriteit, t.status, t.deadline, t.bron,
           t.toegewezen_aan, t.created_at
      from mens m
      join public.taak t
        on t.status <> 'klaar'
       and (
             /* op zijn naam */
             t.toegewezen_aan = m.id
             /* of bij zijn rol, op een vestiging waar hij bij mag */
             or (t.toegewezen_aan is null
                 and t.toegewezen_rol is not null
                 and t.toegewezen_rol = any(m.roles)
                 and (t.location_id is null
                      or m.overal
                      or t.location_id = any(m.locaties)))
           )
  )
  select
    wie,
    wie_naam,
    wie_mail,
    count(*)::integer,
    count(*) filter (where deadline is not null
                       and deadline < (extract(epoch from now()) * 1000)::bigint)::integer,
    jsonb_agg(
      jsonb_build_object(
        'titel', titel,
        'prioriteit', prioriteit,
        'status', status,
        'deadline', deadline,
        'bron', bron,
        'vanRol', toegewezen_aan is null
      )
      /* Het dringendst bovenaan, net als in het scherm: urgent voor hoog voor
         normaal voor laag, en binnen dezelfde prioriteit de vroegste deadline.
         nulls last, want een taak zonder datum is niet dringender dan een die
         morgen af moet. */
      order by case prioriteit
                 when 'urgent' then 0 when 'hoog' then 1
                 when 'normaal' then 2 else 3 end,
               deadline nulls last,
               created_at
    )
  from paren
  group by wie, wie_naam, wie_mail;
$$;

/* Alleen de serverfunctie. Deze functie leest langs RLS heen -- ze moet wel,
   want ze maakt de lijst voor iemand anders dan de beller -- en dat is precies
   waarom niemand anders haar mag aanroepen. */
revoke execute on function public.taken_voor_mail() from public, anon, authenticated;
grant  execute on function public.taken_voor_mail() to service_role;

-- --- ingeschreven door scripts/migratie-stand.cjs ---
do $stand$ begin
  if to_regprocedure('public.migratie_gedaan(integer,text)') is not null then
    perform public.migratie_gedaan(70, 'De takenmail: om 7 en om 15 uur wat er bij je ligt');
  end if;
end $stand$;

-- ===========================================================================
--  Documentbeheer
--
--  Casper: "Nu moet je ook documentbeheer in de app maken (...) Je moet
--  documenten@domein doen, als het daarnaartoe gestuurd wordt, dan moet het
--  daarin komen, in een algemene postvak, en dan kan iemand het bij iemand,
--  afdeling (locatie) ect zetten. Je moet dingen kunnen afschermen, zichtbaar
--  voor jezelf hebben (...) Ook een soort verkenner idee erin (...) deze
--  documenten moet je ook aan een todo kunnen neerhangen."
--
--  Wat er al was en waarom dit er los naast staat
--  ---------------------------------------------
--
--  Er staan al bestanden in dit systeem, maar allemaal met een eigenaar die
--  ze vasthoudt: een bijlage hangt aan een kostenpost (emmer "post"), een
--  contract aan een dossier (emmer "dossiers"), een foto aan een vestiging.
--  Dat is geen documentbeheer maar een bijlage bij iets anders -- je kunt er
--  niet doorheen bladeren, niets verplaatsen, en niets bewaren dat nergens
--  bij hoort.
--
--  Dit is de map waar een document zelf het onderwerp is.
--
--  Drie tabellen en een reden
--  --------------------------
--
--    doc_map       de verkenner: mappen in mappen
--    doc_bestand   het document zelf
--    doc_toegang   met wie het los is gedeeld
--
--  De toegang staat NIET als lijst in een kolom op het bestand. Dat zou
--  kunnen, maar dan kun je niet vragen "welke documenten zijn met mij
--  gedeeld" zonder elke rij te openen, en kun je er ook niet bij zetten wie
--  het deelde en wanneer. Bij een document dat is afgeschermd is dat precies
--  wat je later wilt weten.
--
--  Waarom er een emmer en een pad in de rij staan
--  ----------------------------------------------
--
--  Casper: "uiteindelijk eentje die ik kan integreren met een NAS".
--
--  Die NAS bouw ik nu niet. Maar de plek waar een bestand ligt staat daarom
--  wel als gegeven in de rij en niet als aanname in de code: opslag zegt
--  WAAR het ligt, emmer en pad zeggen waar precies. Een document dat straks
--  op de NAS staat is dan een rij met opslag = 'nas' en verder hetzelfde --
--  en niet een tweede tabel naast deze.
--
--  Opnieuw draaien mag.
-- ===========================================================================

-- ---------------------------------------------------------------------------
--  Wie mag er bij het documentbeheer
--
--  Dezelfde drie als bij het werk: leidinggevende, management, ontwikkelaar.
--  Daarnaast ziet iedereen wat persoonlijk bij hem is neergelegd of met hem
--  is gedeeld -- anders kun je een loonstrook wel bij iemand zetten maar ziet
--  hij hem nooit.
-- ---------------------------------------------------------------------------

create or replace function public.mag_documenten()
returns boolean language sql stable as $$
  select public.is_lead() or public.is_developer();
$$;

grant execute on function public.mag_documenten() to authenticated;

-- ---------------------------------------------------------------------------
--  De mappen
-- ---------------------------------------------------------------------------

create table if not exists public.doc_map (
  id          text primary key,
  naam        text not null,
  /* De verkenner. cascade bij verwijderen: een map weggooien haalt de mappen
     eronder mee. De bestanden niet -- die vallen terug naar het postvak, zie
     doc_bestand.map_id. Een document dat verdwijnt omdat iemand een map
     opruimde is precies wat niet mag. */
  ouder_id    text references public.doc_map(id) on delete cascade,

  /* Van welke vestiging. Null = van het hele bedrijf. */
  location_id text,

  /* Gevuld = een privémap; alleen deze persoon ziet hem en wat erin zit.
     Dat is de "zichtbaar voor jezelf" uit de opdracht. */
  eigenaar    text,

  volgorde    integer not null default 0,
  door        text,
  door_naam   text,
  created_at  bigint not null default public.now_ms(),
  updated_at  bigint not null default public.now_ms()
);

create index if not exists doc_map_ouder_idx on public.doc_map (ouder_id);
create index if not exists doc_map_loc_idx   on public.doc_map (location_id);

comment on table public.doc_map is
  'De mappenstructuur van het documentbeheer (0071). eigenaar gevuld = een '
  'privémap.';

-- ---------------------------------------------------------------------------
--  Het document
-- ---------------------------------------------------------------------------

create table if not exists public.doc_bestand (
  id           text primary key,
  naam         text not null,
  omschrijving text,

  /* Leeg = het algemene postvak. Daar komt binnen wat per mail arriveert, en
     daar blijft het tot iemand het ergens neerzet. */
  map_id       text references public.doc_map(id) on delete set null,

  /* Waar het bestand ligt. Zie de kop: dit staat als gegeven in de rij zodat
     een NAS later geen tweede tabel wordt. */
  opslag       text not null default 'supabase'
               check (opslag in ('supabase', 'nas')),
  emmer        text not null default 'documenten',
  pad          text not null,
  mime         text,
  grootte      bigint,

  bron         text not null default 'upload'
               check (bron in ('upload', 'mail', 'scan')),
  /* Bij bron = mail: het bericht waar hij uit kwam, zodat je van het document
     terug kunt naar de mail met de afzender erbij. */
  bron_id      text,

  /*
   * Wie het mag zien.
   *
   *   prive      alleen de eigenaar (en wie het los gedeeld heeft gekregen)
   *   personen   alleen wie in doc_toegang staat
   *   vestiging  iedereen met documentrechten op die vestiging
   *   rollen     iedereen met documentrechten in een van deze rollen
   *   iedereen   iedereen met documentrechten
   *
   * Standaard "vestiging" en niet "iedereen": een document hoort niet breder
   * te staan dan waar het over gaat, en de smalle stand is de stand die je
   * per ongeluk goed hebt.
   */
  zichtbaarheid text not null default 'vestiging'
                check (zichtbaarheid in ('prive', 'personen', 'vestiging', 'rollen', 'iedereen')),
  eigenaar     text,
  location_id  text,
  rollen       text[] not null default '{}',

  /* Bij wie het is neergelegd. Die ziet het altijd, ook zonder
     documentrechten -- anders kun je een contract wel bij iemand zetten maar
     krijgt hij het nooit te zien. */
  toegewezen_aan  text,
  toegewezen_naam text,

  door         text,
  door_naam    text,
  created_at   bigint not null default public.now_ms(),
  updated_at   bigint not null default public.now_ms()
);

create index if not exists doc_bestand_map_idx  on public.doc_bestand (map_id);
create index if not exists doc_bestand_loc_idx  on public.doc_bestand (location_id);
create index if not exists doc_bestand_wie_idx  on public.doc_bestand (toegewezen_aan);
create index if not exists doc_bestand_bron_idx on public.doc_bestand (bron, bron_id);

/* Eén document per bijlage uit één mail. Zonder dit maakt een mail die twee
   keer wordt aangeboden -- en dat gebeurt, webhooks worden opnieuw geprobeerd
   -- twee identieke rijen in het postvak. */
create unique index if not exists doc_bestand_uit_mail
  on public.doc_bestand (bron_id, pad) where bron = 'mail';

comment on table public.doc_bestand is
  'Documenten (0071). map_id leeg = het algemene postvak. Wie het mag zien '
  'staat in zichtbaarheid; mag_document() rekent het uit.';

-- ---------------------------------------------------------------------------
--  Los gedeeld
-- ---------------------------------------------------------------------------

create table if not exists public.doc_toegang (
  /* Een eigen id en niet document_id + profile_id als sleutel. Twee redenen,
     en de tweede is de zwaarste: de synchronisatie van de app vergelijkt elke
     tabel op één kolom die id heet, en een samengestelde sleutel komt daar
     nooit doorheen. De eerste is rij_bestaat() -- de uitweg uit de upsert-val
     (0044) zoekt op id. */
  id          text primary key,
  document_id text not null references public.doc_bestand(id) on delete cascade,
  profile_id  text not null,
  door        text,
  door_naam   text,
  created_at  bigint not null default public.now_ms(),
  updated_at  bigint not null default public.now_ms()
);

/* Twee keer dezelfde persoon bij hetzelfde document is geen tweede deling. */
create unique index if not exists doc_toegang_uniek
  on public.doc_toegang (document_id, profile_id);
create index if not exists doc_toegang_wie_idx on public.doc_toegang (profile_id);

comment on table public.doc_toegang is
  'Met wie een afgeschermd document los is gedeeld (0071), met wie het deelde '
  'en wanneer -- juist bij een afgeschermd document is dat wat je later wilt '
  'weten.';

-- ---------------------------------------------------------------------------
--  Aan een taak hangen
--
--  Casper: "deze documenten moet je ook aan een todo kunnen neerhangen".
--
--  Een eigen tabel en geen kolom op de taak: aan één taak kunnen meer
--  documenten hangen, en hetzelfde document kan bij meer taken horen -- een
--  keuringsrapport hoort bij de reparatie én bij de jaarlijkse controle.
-- ---------------------------------------------------------------------------

create table if not exists public.taak_document (
  /* Zie doc_toegang hierboven voor waarom hier een eigen id staat. */
  id          text primary key,
  taak_id     text not null references public.taak(id) on delete cascade,
  document_id text not null references public.doc_bestand(id) on delete cascade,
  door        text,
  created_at  bigint not null default public.now_ms(),
  updated_at  bigint not null default public.now_ms()
);

create unique index if not exists taak_document_uniek
  on public.taak_document (taak_id, document_id);
create index if not exists taak_document_doc_idx on public.taak_document (document_id);

-- ---------------------------------------------------------------------------
--  Mag ik bij dit document?
--
--  Op één plek, want dit wordt op vier plekken gevraagd: bij het document
--  zelf, bij de losse deling, bij de koppeling aan een taak, en bij het
--  bestand in de opslag. Vier keer dezelfde regel overtypen is drie kansen om
--  hem net iets anders op te schrijven.
--
--  security definer omdat hij doc_bestand leest terwijl er juist een regel op
--  doc_bestand wordt beoordeeld.
-- ---------------------------------------------------------------------------

create or replace function public.mag_document(doc text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1
      from public.doc_bestand b
     where b.id = doc
       and (
         /* Van mij, bij mij neergelegd, of met mij gedeeld. Deze drie gelden
            altijd -- ook zonder documentrechten, anders kun je een contract
            wel bij iemand zetten maar ziet hij het nooit. */
         b.eigenaar = public.my_id()
         or b.toegewezen_aan = public.my_id()
         or exists (select 1 from public.doc_toegang t
                     where t.document_id = b.id and t.profile_id = public.my_id())

         /* En de brede standen, alleen voor wie bij het documentbeheer mag. */
         or (public.mag_documenten() and (
               b.zichtbaarheid = 'iedereen'
               or (b.zichtbaarheid = 'rollen' and b.rollen && public.my_roles())
               or (b.zichtbaarheid = 'vestiging' and public.in_my_locations(b.location_id))
             ))
       )
  );
$$;

/* Supabase geeft een nieuwe functie standaard aan PUBLIC, en daarmee ook aan
   anon. Bij een security definer-functie die leest wie wat mag zien, is dat
   een open deur -- vandaar eerst intrekken en dan gericht uitdelen. */
revoke execute on function public.mag_document(text) from public, anon;
grant  execute on function public.mag_document(text) to authenticated;

-- ---------------------------------------------------------------------------
--  Wie mag hierbij
-- ---------------------------------------------------------------------------

alter table public.doc_map       enable row level security;
alter table public.doc_bestand   enable row level security;
alter table public.doc_toegang   enable row level security;
alter table public.taak_document enable row level security;

/* --- mappen --- */

drop policy if exists doc_map_select on public.doc_map;
create policy doc_map_select on public.doc_map
  for select to authenticated
  using (
    eigenaar = public.my_id()
    or (eigenaar is null and public.mag_documenten() and public.in_my_locations(location_id))
  );

drop policy if exists doc_map_insert on public.doc_map;
create policy doc_map_insert on public.doc_map
  for insert to authenticated
  /* rij_bestaat() vooraan om dezelfde reden als overal: een upsert langs
     PostgREST beoordeelt deze regel OOK bij een gewone wijziging. Zie 0044. */
  with check (public.rij_bestaat('public.doc_map'::regclass, id)
              or (public.mag_documenten()
                  and (eigenaar is null or eigenaar = public.my_id())
                  and public.in_my_locations(location_id)));

drop policy if exists doc_map_update on public.doc_map;
create policy doc_map_update on public.doc_map
  for update to authenticated
  using (eigenaar = public.my_id()
         or (eigenaar is null and public.mag_documenten() and public.in_my_locations(location_id)))
  with check (eigenaar = public.my_id()
              or (eigenaar is null and public.mag_documenten() and public.in_my_locations(location_id)));

/* Een map weggooien haalt de mappen eronder mee (cascade) maar de bestanden
   niet: die vallen terug naar het postvak. Daarom mag dit alleen wie de map
   ook mocht maken. */
drop policy if exists doc_map_delete on public.doc_map;
create policy doc_map_delete on public.doc_map
  for delete to authenticated
  using (eigenaar = public.my_id()
         or (eigenaar is null and public.mag_documenten() and public.in_my_locations(location_id)));

/* --- documenten --- */

drop policy if exists doc_bestand_select on public.doc_bestand;
create policy doc_bestand_select on public.doc_bestand
  for select to authenticated using (public.mag_document(id));

drop policy if exists doc_bestand_insert on public.doc_bestand;
create policy doc_bestand_insert on public.doc_bestand
  for insert to authenticated
  with check (public.rij_bestaat('public.doc_bestand'::regclass, id)
              or (public.mag_documenten() and public.in_my_locations(location_id)));

drop policy if exists doc_bestand_update on public.doc_bestand;
create policy doc_bestand_update on public.doc_bestand
  for update to authenticated
  using (public.mag_documenten() and public.mag_document(id))
  with check (public.mag_documenten() and public.in_my_locations(location_id));

/* Wissen doet alleen wie er ook bij mag, en het bestand in de opslag gaat
   apart -- die twee kunnen niet in één handeling, dus de app ruimt op. */
drop policy if exists doc_bestand_delete on public.doc_bestand;
create policy doc_bestand_delete on public.doc_bestand
  for delete to authenticated
  using (public.mag_documenten() and public.mag_document(id));

/* --- delingen --- */

drop policy if exists doc_toegang_select on public.doc_toegang;
create policy doc_toegang_select on public.doc_toegang
  for select to authenticated
  using (profile_id = public.my_id() or public.mag_document(document_id));

drop policy if exists doc_toegang_insert on public.doc_toegang;
create policy doc_toegang_insert on public.doc_toegang
  for insert to authenticated
  with check (public.rij_bestaat('public.doc_toegang'::regclass, id)
              or (public.mag_documenten() and public.mag_document(document_id)));

drop policy if exists doc_toegang_delete on public.doc_toegang;
create policy doc_toegang_delete on public.doc_toegang
  for delete to authenticated
  using (public.mag_documenten() and public.mag_document(document_id));

/* --- aan een taak --- */

drop policy if exists taak_document_select on public.taak_document;
create policy taak_document_select on public.taak_document
  for select to authenticated using (public.mag_document(document_id));

drop policy if exists taak_document_insert on public.taak_document;
create policy taak_document_insert on public.taak_document
  for insert to authenticated
  with check (public.rij_bestaat('public.taak_document'::regclass, id)
              or (public.mag_document(document_id)
                  and exists (select 1 from public.taak t where t.id = taak_id)));

drop policy if exists taak_document_delete on public.taak_document;
create policy taak_document_delete on public.taak_document
  for delete to authenticated using (public.mag_document(document_id));

-- ---------------------------------------------------------------------------
--  De emmer
--
--  Dicht, net als "dossiers" en "post". Downloaden gaat met een ondertekende
--  link van zestig seconden; er is geen openbaar adres.
--
--  De leesregel hangt aan mag_document(), zodat de afscherming niet te
--  omzeilen is door het bestand rechtstreeks op te vragen. Dat is precies de
--  fout die een documentsysteem onbruikbaar maakt: de lijst verbergt iets wat
--  de opslag gewoon uitdeelt.
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'documenten', 'documenten', false, 52428800,
  array[
    'application/pdf',
    'image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/gif',
    'text/plain', 'text/csv',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.ms-powerpoint',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'application/zip'
  ]
)
on conflict (id) do update
   set public = false,
       file_size_limit = excluded.file_size_limit,
       allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists documenten_lezen on storage.objects;
create policy documenten_lezen on storage.objects for select to authenticated
  using (
    bucket_id = 'documenten'
    and exists (
      select 1 from public.doc_bestand b
       where b.pad = storage.objects.name
         and b.emmer = 'documenten'
         and public.mag_document(b.id)
    )
  );

/* Neerzetten mag wie bij het documentbeheer mag. De rij ernaast wordt door de
   app in dezelfde handeling gemaakt; komt die er niet, dan ligt er een
   bestand dat niemand kan lezen (de leesregel hierboven vindt geen rij) en
   dat de opruiming hieronder weghaalt. */
drop policy if exists documenten_schrijven on storage.objects;
create policy documenten_schrijven on storage.objects for insert to authenticated
  with check (bucket_id = 'documenten' and public.mag_documenten());

drop policy if exists documenten_wissen on storage.objects;
create policy documenten_wissen on storage.objects for delete to authenticated
  using (
    bucket_id = 'documenten'
    and public.mag_documenten()
    and (
      /* Het bestand van een document dat ik mag beheren, of een bestand
         waar geen rij (meer) bij hoort -- dat laatste is een halve upload en
         die hoort opgeruimd te kunnen worden. */
      exists (select 1 from public.doc_bestand b
               where b.pad = storage.objects.name and b.emmer = 'documenten'
                 and public.mag_document(b.id))
      or not exists (select 1 from public.doc_bestand b
                      where b.pad = storage.objects.name and b.emmer = 'documenten')
    )
  );

-- ---------------------------------------------------------------------------
--  En de emmer waar de post al in ligt
--
--  Een bijlage die per mail binnenkomt blijft staan waar hij staat: in de
--  emmer "post". Hem overzetten naar "documenten" zou hetzelfde bestand twee
--  keer opslaan, en de rij zegt al waar hij ligt (emmer + pad).
--
--  Maar de leesregel op die emmer (0011) laat alleen management en
--  ontwikkelaar toe. Een leidinggevende zou een document in het postvak dus
--  wél zien staan en het niet kunnen openen -- een lijst die iets toont wat
--  de opslag weigert, en dat is precies het soort fout waarvan je denkt dat
--  het aan je verbinding ligt.
--
--  Vandaar deze regel erbij. De oude voorwaarde blijft ongewijzigd staan; er
--  komt alleen een tweede weg naast: er hangt een document aan dit bestand en
--  je mag bij dat document.
-- ---------------------------------------------------------------------------

drop policy if exists post_lezen on storage.objects;
create policy post_lezen on storage.objects for select to authenticated
  using (
    bucket_id = 'post'
    and (
      public.is_management() or public.is_developer()
      or exists (
        select 1 from public.doc_bestand b
         where b.pad = storage.objects.name
           and b.emmer = 'post'
           and public.mag_document(b.id)
      )
    )
  );

-- ---------------------------------------------------------------------------
--  Het adres waar documenten binnenkomen
--
--  Casper: "Je moet documenten@domein doen".
--
--  Als instelling en niet in de code: het domein staat al als
--  inkoop_domein en het voorvoegsel hoort daar naast te kunnen staan zonder
--  dat er een versie voor uit hoeft.
-- ---------------------------------------------------------------------------

insert into public.instellingen (id, sleutel, waarde, omschrijving) values
  ('in_documenten_voorvoegsel', 'documenten_voorvoegsel', 'documenten',
   'Het postvak waar documenten binnenkomen, vóór de @. Post aan dit adres '
   'wordt geen kostenpost maar belandt in het algemene postvak van het '
   'documentbeheer. Leeg laten zet het uit.')
on conflict (id) do nothing;

-- --- ingeschreven door scripts/migratie-stand.cjs ---
do $stand$ begin
  if to_regprocedure('public.migratie_gedaan(integer,text)') is not null then
    perform public.migratie_gedaan(71, 'Documentbeheer');
  end if;
end $stand$;

-- ===========================================================================
--  De administratie komt binnen
--
--  Aanleiding: de verbouwing van het administratiedashboard. Voordat er ook
--  maar een scherm verhuist moet dit recht staan, want anders lever ik lege
--  schermen op.
--
--  Wat er aan de hand is
--  ---------------------
--
--  heeft_recht() kijkt uitsluitend naar profiles.grants. De rol administratie
--  krijgt admin.desk, finance.view en expenses.approve uit de ROL
--  (permissions.ts), en de app schrijft een rolrecht daar bewust niet in --
--  zie togglePermission: "if (enabled && !fromRole) grants.add(...)".
--
--  Gevolg: 22 policies staan op `is_management() or heeft_recht('admin.desk')`
--  en geven een echte administratiemedewerker nul rijen. Geen foutmelding,
--  geen lege staat, gewoon een tabel die leeg blijft: verkoopfactuur,
--  verkoopregel, betaalbatch, betaalregel, exact_relatie, company_exact,
--  grootboek, kosten_tags, instellingen. Dat geldt NU al voor Kostenposten;
--  het valt alleen niemand op omdat het account dat ermee werkt ook
--  management is.
--
--  Waarom niet: heeft_recht() alle roldefaults laten lezen
--  ------------------------------------------------------
--
--  Dat was de eerste ingeving en hij is fout. Nageteld welke rechten de
--  database via heeft_recht() gebruikt en wie ze er dan bij zou krijgen:
--
--    staff.view      6 policies  -> de leidinggevende krijgt het personeel
--    hours.approve   4 policies  -> idem
--    chat.manage     3 policies  -> idem
--
--  0056 legt met zoveel woorden vast dat staff.view voor een leidinggevende
--  juist false hoort te zijn. Een regel die dat stilletjes omdraait is precies
--  het soort wijziging waarvan je een half jaar later niet meer weet dat je
--  hem hebt gedaan. Dus niet alles, maar een lijst die je kunt lezen.
--
--  Wat het wel wordt: een brug die je kunt navragen
--  -----------------------------------------------
--
--  Een tabel, rol_recht, met precies de rolrechten die de database mag
--  afleiden. Vandaag staan daar alleen de vijf rijen van de administratie in.
--  Wil je er later een bij, dan is dat een regel in een migratie en geen
--  nieuwe policy -- en `select * from rol_recht` vertelt je zonder graven wat
--  de database aanneemt.
--
--  Een intrekking wint. Zet het management admin.desk bij iemand uit, dan gaat
--  de brug dicht. Dat werkte bij grants niet en werkt hier wel; de grants-kant
--  laat ik met opzet staan zoals hij was, dat is een aparte beslissing.
--
--  Verder in deze migratie
--  -----------------------
--
--    * mailbox_select/_update/_insert en post_lezen: de postbus en de
--      bijlagen. Select alleen verruimen is een val -- Postbus markeert een
--      bericht als gelezen zodra je erop klikt, dus zonder _update loopt de
--      wachtrij vast op elk geopend bericht.
--    * instellingen_insert/_update voor de boekhoudsleutels, naar het model
--      van is_trucksupply_instelling(). Niet alle sleutels: app_url en de
--      sleutels van de Exact-koppeling blijven van het management.
--
--  Opnieuw draaien mag.
-- ===========================================================================

-- ---------------------------------------------------------------------------
--  1. De brug van rol naar recht
-- ---------------------------------------------------------------------------

create table if not exists public.rol_recht (
  rol        text not null,
  recht      text not null,
  waarom     text,
  primary key (rol, recht)
);

comment on table public.rol_recht is
  'Welke rechten de database uit een ROL mag afleiden. Bewust een korte lijst: permissions.ts geeft er veel meer, maar niet alles hoort de database te weten.';

alter table public.rol_recht enable row level security;

/* Wie ingelogd is mag deze lijst lezen -- het is geen geheim wat de regels
   zijn, en heeft_recht() draait als security definer dus die komt er sowieso
   bij. Schrijven doet alleen een migratie. */
drop policy if exists rol_recht_select on public.rol_recht;
create policy rol_recht_select on public.rol_recht for select to authenticated
  using (true);

insert into public.rol_recht (rol, recht, waarom) values
  ('administratie', 'admin.desk',
   'De boekhouding: verkoopfacturen, betalen, relaties, grootboek, instellingen.'),
  ('administratie', 'finance.view',
   'Een kostenpost beoordelen zonder de maand te zien is stempelen.'),
  ('administratie', 'expenses.approve',
   'De eerste handtekening onder een bon.'),
  ('administratie', 'expenses.read',
   'De bon zelf mogen openen, niet alleen de regel eromheen.'),
  ('administratie', 'mail.read',
   'De inkoopmail is waar de bonnen vandaan komen.')
on conflict (rol, recht) do update set waarom = excluded.waarom;

-- ---------------------------------------------------------------------------
--  2. heeft_recht() kijkt ook over de brug
--
--  De grants-kant blijft letterlijk wat hij was. Erbij komt: het recht dat een
--  rol geeft en dat in rol_recht staat, tenzij het bij deze persoon is
--  ingetrokken.
-- ---------------------------------------------------------------------------

create or replace function public.heeft_recht(recht text)
returns boolean language sql stable security definer set search_path = public as $$
  select recht = any(
           coalesce((select grants from public.profiles where auth_id = auth.uid()),
                    array[]::text[]))
      or (
        not (recht = any(
               coalesce((select revokes from public.profiles where auth_id = auth.uid()),
                        array[]::text[])))
        and exists (
          select 1 from public.rol_recht rr
           where rr.recht = heeft_recht.recht
             and rr.rol = any(public.my_roles())
        )
      );
$$;

/* Supabase geeft elke nieuwe functie aan PUBLIC. Deze bestond al, maar
   `create or replace` zet de rechten niet vanzelf terug. */
revoke execute on function public.heeft_recht(text) from public, anon;
grant  execute on function public.heeft_recht(text) to authenticated, service_role;

-- ---------------------------------------------------------------------------
--  3. is_administratie(), voor policies die een rol noemen
--
--  Naast is_management() en is_trucksupply(). Nodig waar er geen recht in het
--  spel is maar een rol, zoals bij de postbus.
-- ---------------------------------------------------------------------------

create or replace function public.is_administratie()
returns boolean language sql stable security definer set search_path = public as $$
  select 'administratie' = any(public.my_roles());
$$;

revoke execute on function public.is_administratie() from public, anon;
grant  execute on function public.is_administratie() to authenticated, service_role;

-- ---------------------------------------------------------------------------
--  4. De postbus
--
--  De app laat de administratie al binnen (permissions.ts geeft de rol
--  mail.read en Postbus.tsx kijkt daarnaar), de database niet. Dat levert geen
--  foutmelding op maar een leeg scherm -- erger dan geen toegang, want het
--  liegt.
--
--  _update moet mee. Postbus markeert een bericht als gelezen op het moment
--  dat je erop klikt; dat is een put, die gaat de wachtrij in, en een
--  weigering daar blijft staan en wordt elke synchronisatieronde opnieuw
--  geprobeerd.
-- ---------------------------------------------------------------------------

drop policy if exists mailbox_select on public.mailbox;
create policy mailbox_select on public.mailbox for select to authenticated
  using (public.is_management() or public.is_developer() or public.is_administratie());

drop policy if exists mailbox_update on public.mailbox;
create policy mailbox_update on public.mailbox for update to authenticated
  using (public.is_management() or public.is_developer() or public.is_administratie())
  with check (public.is_management() or public.is_developer() or public.is_administratie());

drop policy if exists mailbox_insert on public.mailbox;
create policy mailbox_insert on public.mailbox for insert to authenticated
  with check (
    public.rij_bestaat('public.mailbox'::regclass, id::text)
    or public.is_management() or public.is_developer() or public.is_administratie()
  );

/* Wissen blijft bij het management. Een bericht weggooien is iets anders dan
   het lezen, en de administratie heeft er geen reden voor. */

-- ---------------------------------------------------------------------------
--  5. De bijlagen bij die berichten
--
--  Zonder deze regel zie je de naam van de bijlage wel staan en gaat er niets
--  open: createSignedUrl faalt op de emmer. Precies de leesketen waar de
--  verbouwing een beeld-terugval op wil bouwen.
-- ---------------------------------------------------------------------------

drop policy if exists post_lezen on storage.objects;
create policy post_lezen on storage.objects for select to authenticated
  using (
    bucket_id = 'post'
    and (
      public.is_management() or public.is_developer() or public.is_administratie()
      or exists (
        select 1 from public.doc_bestand b
         where b.pad = storage.objects.name
           and b.emmer = 'post'
           and public.mag_document(b.id)
      )
    )
  );

-- ---------------------------------------------------------------------------
--  6. De instellingen die bij de boekhouding horen
--
--  instellingen_select liet admin.desk al door, _insert en _update niet. Dat
--  is de stilste fout van allemaal: Dexie slaat het lokaal op, het scherm zegt
--  "opgeslagen", en de rij blijft op een 42501 in de wachtrij hangen.
--
--  Niet alle sleutels. Naar het model van is_trucksupply_instelling(): een
--  lijst die je kunt lezen. app_url en site_url horen bij het management --
--  daar wijst elke knop in elke mail heen. exact_division ook niet: die staat
--  al op de lijst van trucksupply en wordt door de serverfunctie geschreven,
--  die met de servicesleutel werkt en dus buiten RLS om gaat.
-- ---------------------------------------------------------------------------

create or replace function public.is_boekhoud_instelling(sleutel text)
returns boolean language sql stable as $$
  /* Nageteld tegen de sleutels die echt bestaan, niet tegen wat logisch
     klinkt: een sleutel die nergens wordt gelezen staat hier voor niets, en
     een die ik verkeerd spel valt stil buiten de lijst. */
  select sleutel in (
    /* het lezen van facturen */
    'factuur_lezer', 'factuur_automatisch',
    'lezer_model', 'lezer_stand', 'lezer_laatst_gezien',
    'auto_goedkeuren', 'auto_goedkeuren_marge',
    'auto_goedkeuren_max', 'auto_goedkeuren_vanaf',
    'vier_ogen', 'vier_ogen_vanaf',
    /* waar het heen wordt geboekt */
    'exact_facturen', 'exact_dagboek', 'exact_verkoopdagboek',
    'exact_btw_21', 'exact_btw_9', 'exact_btw_0',
    /* de eigen gegevens op een verkoopfactuur */
    'eigen_kvk', 'eigen_btw', 'eigen_iban',
    /* waar de inkoopmail binnenkomt */
    'inkoop_domein', 'inkoop_voorvoegsel'
  )
$$;

revoke execute on function public.is_boekhoud_instelling(text) from public, anon;
grant  execute on function public.is_boekhoud_instelling(text) to authenticated, service_role;

drop policy if exists instellingen_insert on public.instellingen;
create policy instellingen_insert on public.instellingen for insert to authenticated
  with check (
    public.rij_bestaat('public.instellingen'::regclass, id)
    or public.is_management()
    or (public.heeft_recht('admin.desk') and public.is_boekhoud_instelling(sleutel))
    or ((public.is_trucksupply() or public.heeft_recht('supply.settings'))
        and public.is_trucksupply_instelling(sleutel))
  );

drop policy if exists instellingen_update on public.instellingen;
create policy instellingen_update on public.instellingen for update to authenticated
  using (
    public.is_management()
    or (public.heeft_recht('admin.desk') and public.is_boekhoud_instelling(sleutel))
    or ((public.is_trucksupply() or public.heeft_recht('supply.settings'))
        and public.is_trucksupply_instelling(sleutel))
  )
  with check (
    public.is_management()
    or (public.heeft_recht('admin.desk') and public.is_boekhoud_instelling(sleutel))
    or ((public.is_trucksupply() or public.heeft_recht('supply.settings'))
        and public.is_trucksupply_instelling(sleutel))
  );

-- --- ingeschreven door scripts/migratie-stand.cjs ---
do $stand$ begin
  if to_regprocedure('public.migratie_gedaan(integer,text)') is not null then
    perform public.migratie_gedaan(72, 'De administratie komt binnen');
  end if;
end $stand$;

-- ===========================================================================
--  Een nagekomen wasbeurt blokkeert niet de hele ronde
--
--  Gevonden bij de verkenning voor de verbouwing van het administratie-
--  dashboard, en nagespeeld met PGlite. Het is geen theoretisch geval: het
--  gebeurt zodra iemand een wasbeurt achteraf gereedmeldt, en dat gebeurt.
--
--  Wat er misging
--  --------------
--
--  verkoopfacturen_opmaken() (0064) loopt per klant. Voor elke klant zoekt hij
--  eerst of er al een CONCEPT over die maand ligt om in bij te vullen. Ligt er
--  geen concept, dan maakt hij er een met een id dat volledig uit de maand en
--  het klantnummer wordt opgebouwd:
--
--      f_id := 'vf_' || replace(periode_in, '-', '') || '_' || klant.company_id
--
--  Dat id is dus altijd hetzelfde voor dezelfde klant en dezelfde maand. En
--  daar gaat het mis:
--
--    1. Klant A heeft een wasbeurt in mei. Opmaken geeft concept
--       vf_202605_co_a. Versturen zet hem op 'verstuurd' met een nummer.
--    2. Er komt een tweede wasbeurt van klant A over mei binnen. En een
--       eerste van klant B.
--    3. Opmaken loopt weer. Voor klant A is er geen concept (die staat op
--       verstuurd), dus bouwt hij hetzelfde id opnieuw. De insert doet niets
--       (on conflict do nothing) -- maar gemaakt wordt wel opgeteld.
--    4. Daarna schiet hij de nieuwe regel in factuur_id vf_202605_co_a, en dat
--       is de VERSTUURDE factuur. De trigger verkoopregel_op_slot (0064:161)
--       gooit er terecht een fout op: "Deze factuur is niet meer concept; de
--       regels liggen vast."
--    5. Die fout komt uit een functie, dus de hele ronde draait terug.
--       Klant B krijgt niets. En morgen weer niets, want de oorzaak blijft.
--
--  Eén nagekomen wasbeurt zet daarmee de facturatie van alle achttien
--  vestigingen stil, met een foutmelding die over factuur A gaat terwijl het
--  probleem is dat B niets krijgt.
--
--  Wat het nu doet
--  ---------------
--
--  Is het voor de hand liggende id al bezet, dan zoekt hij een vrij id met een
--  achtervoegsel (_na2, _na3). Die beurten zijn nagekomen en horen op een
--  eigen naregel-factuur -- niet in een factuur die de klant al op papier
--  heeft, en niet in een factuur die er niet komt.
--
--  En gemaakt wordt geteld met get diagnostics, dus alleen als er echt een rij
--  is bijgekomen. Dat is niet cosmetisch: het scherm meldt "3 concepten
--  opgemaakt" en daar hangt iemand zijn controle aan.
--
--  Wat er NIET verandert: de trigger blijft staan zoals hij is. Die had het
--  goed; hij hield tegen dat er in een verstuurde factuur werd geschreven.
--  Het was de aanroeper die hem in die situatie bracht.
--
--  Opnieuw draaien mag.
-- ===========================================================================

create or replace function public.verkoopfacturen_opmaken(
  periode_in text,
  door_in    text default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  vanaf   bigint;
  tot     bigint;
  klant   record;
  f_id    text;
  basis   text;
  poging  integer;
  gemaakt integer := 0;
  n       integer;
begin
  /* De maand als 2026-03. Begin en einde in milliseconden, want zo staat de
     tijd overal in dit schema. */
  vanaf := (extract(epoch from (periode_in || '-01')::date) * 1000)::bigint;
  tot   := (extract(epoch from ((periode_in || '-01')::date + interval '1 month')) * 1000)::bigint;

  for klant in
    select j.company_id, min(j.company_name) as naam, count(*) as beurten
      from public.wash_jobs j
     where j.status = 'gereed'
       and j.completed_at >= vanaf and j.completed_at < tot
       and coalesce(j.price_excl, 0) > 0
       and not exists (select 1 from public.verkoopregel r where r.wash_job_id = j.id)
     group by j.company_id
  loop
    /* Al een concept voor deze klant en deze maand? Dan daarin bijvullen in
       plaats van een tweede maken -- anders krijgt de klant twee facturen
       over dezelfde maand omdat er een beurt later is bijgeboekt. */
    select f.id into f_id
      from public.verkoopfactuur f
     where f.company_id = klant.company_id
       and f.periode = periode_in
       and f.status = 'concept'
     limit 1;

    if f_id is null then
      /*
       * Geen concept. Er kan wél een verstuurde, betaalde of vervallen
       * factuur over deze maand liggen, en dan is het voor de hand liggende
       * id al bezet. Vroeger werd dat id dan alsnog gebruikt, en gingen de
       * regels de verstuurde factuur in -- waar de trigger op afging en de
       * hele ronde mee omviel.
       *
       * Dus: een vrij id zoeken. De lus loopt hoogstens zo vaak als er al
       * facturen voor deze klant en maand zijn, en dat is een handvol.
       */
      basis := 'vf_' || replace(periode_in, '-', '') || '_' || klant.company_id;
      f_id := basis;
      poging := 1;
      while exists (select 1 from public.verkoopfactuur f where f.id = f_id) loop
        poging := poging + 1;
        f_id := basis || '_na' || poging;
      end loop;

      insert into public.verkoopfactuur
        (id, company_id, company_naam, periode, datum, vervaldatum, administratie, opmerking)
      values (
        f_id, klant.company_id, klant.naam, periode_in,
        tot - 1,
        tot - 1 + (30::bigint * 24 * 60 * 60 * 1000),
        (select a.code from public.exact_administratie a where a.hoofd limit 1),
        case
          when poging = 1 then 'Wasbeurten ' || periode_in
          /* Zeg op de factuur zelf waarom er een tweede is. Anders belt de
             klant en weet niemand het. */
          else 'Wasbeurten ' || periode_in || ' (nagekomen)'
        end)
      on conflict (id) do nothing;

      /*
       * Tellen wat er echt is bijgekomen. Hiervoor stond hier
       * `gemaakt := gemaakt + 1`, ook als de insert door on conflict niets
       * deed -- en dan meldde het scherm concepten die er niet waren.
       */
      get diagnostics n = row_count;
      gemaakt := gemaakt + n;

      /* Niets ingevoegd én geen concept gevonden: dan is er tussen het zoeken
         en het invoegen iets veranderd. Deze klant volgende ronde. */
      if n = 0 then
        f_id := null;
        continue;
      end if;
    end if;

    insert into public.verkoopregel
      (id, factuur_id, volgorde, omschrijving, aantal, prijs_excl, btw_pct, wash_job_id)
    select 'vr_' || j.id,
           f_id,
           row_number() over (order by j.completed_at),
           coalesce(nullif(j.service, ''), 'Wasbeurt') || ' · ' || j.plate,
           1,
           j.price_excl,
           21,
           j.id
      from public.wash_jobs j
     where j.company_id = klant.company_id
       and j.status = 'gereed'
       and j.completed_at >= vanaf and j.completed_at < tot
       and coalesce(j.price_excl, 0) > 0
       and not exists (select 1 from public.verkoopregel r where r.wash_job_id = j.id)
    on conflict (id) do nothing;

    perform public.verkoopfactuur_tellen(f_id);
    f_id := null;
  end loop;

  return gemaakt;
end $$;

/* Zelfde rechten als in 0064: alleen de serverfunctie mag dit. */
revoke execute on function public.verkoopfacturen_opmaken(text, text) from public, anon, authenticated;
grant  execute on function public.verkoopfacturen_opmaken(text, text) to service_role;

comment on function public.verkoopfacturen_opmaken(text, text) is
  'Maakt per klant een conceptverkoopfactuur uit de gereedgemelde wasbeurten van een maand. Ligt er al een verstuurde factuur over die maand, dan komt er een naregel-factuur met een eigen id; nagekomen beurten blokkeren zo niet de facturatie van de andere klanten.';

-- --- ingeschreven door scripts/migratie-stand.cjs ---
do $stand$ begin
  if to_regprocedure('public.migratie_gedaan(integer,text)') is not null then
    perform public.migratie_gedaan(73, 'Een nagekomen wasbeurt blokkeert niet de hele ronde');
  end if;
end $stand$;

-- ===========================================================================
--  Je eigen woonadres invullen
--
--  Casper: "Daarnaast kan ik niet vinden waar ik iemand zijn adres moet
--  invullen voor kilometer vergoeding, of waar ze dit zelf kunnen doen."
--
--  Hij kon het niet vinden omdat het er niet was. Het woonadres staat op
--  personnel_private (address, postcode, city) en er is in de hele app geen
--  enkel scherm dat die drie velden invult -- niet bij het kantoor en niet bij
--  de medewerker zelf. Het ritformulier zegt intussen: "Je woonadres staat nog
--  niet in je dossier ... Vraag het kantoor om het toe te voegen." Het kantoor
--  had dat scherm ook niet.
--
--  Waarom dit niet alleen een schermwijziging is
--  ---------------------------------------------
--
--  prive_select laat je je eigen rij LEZEN (user_id = my_id()), prive_write
--  niet. Schrijven mag alleen management, een leidinggevende, of wie
--  staff.view heeft. Wil iemand zijn eigen adres invullen, dan moet die rij
--  dus open -- en RLS werkt per rij, niet per kolom. Zomaar openzetten
--  betekent dat iedereen zijn eigen BSN, documentnummer en vervaldatum kan
--  wijzigen. Dat is precies waarom 0056 die tabel heeft opgesplitst.
--
--  Hoe het dan wel kan
--  -------------------
--
--  Zelfde aanpak als lezing_blijft_lezing (0049): de policy gaat open, en een
--  trigger zet alles terug wat je niet mocht wijzigen. Schrijf je je eigen
--  rij en ben je geen personeelszaken, dan blijven alle kolommen behalve
--  address, postcode en city staan op hun oude waarde. Geen foutmelding, geen
--  half opgeslagen rij -- de wijziging gebeurt gewoon niet.
--
--  Dat past ook bij de rest van de app: die schrijft eerst lokaal en duwt het
--  daarna via de wachtrij naar de server. Een aparte functie aanroepen zou
--  betekenen dat je adres alleen te wijzigen is met verbinding.
--
--  Waarom dit geen goedkeuring nodig heeft
--  ---------------------------------------
--
--  Een rit legt zijn kilometers vast op het moment dat hij wordt aangemaakt
--  (Trip.km, met bron 'route'); een adreswijziging rekent oude ritten dus niet
--  opnieuw uit. Er valt met terugwerkende kracht niets te verdienen. En wie
--  een verkeerd adres invult benadeelt vooral zichzelf: dan klopt zijn eigen
--  woon-werkafstand niet.
--
--  Opnieuw draaien mag.
-- ===========================================================================

-- ---------------------------------------------------------------------------
--  1. Mag deze persoon het dossier van een ander beheren?
--
--  Eén plek, want dit staat straks in de policy en in de trigger, en die twee
--  horen niet uit elkaar te lopen.
-- ---------------------------------------------------------------------------

create or replace function public.mag_dossiers_beheren()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_management()
      or public.is_supervisor()
      or public.heeft_recht('staff.view');
$$;

revoke execute on function public.mag_dossiers_beheren() from public, anon;
grant  execute on function public.mag_dossiers_beheren() to authenticated, service_role;

-- ---------------------------------------------------------------------------
--  2. De rij gaat open voor de eigenaar
-- ---------------------------------------------------------------------------

drop policy if exists prive_write on public.personnel_private;
create policy prive_write on public.personnel_private for all to authenticated
  using (public.mag_dossiers_beheren() or user_id = public.my_id())
  with check (public.mag_dossiers_beheren() or user_id = public.my_id());

-- ---------------------------------------------------------------------------
--  3. ...maar dan alleen voor de drie adresvelden
--
--  De trigger draait ook bij een insert. Iemand die nog geen dossierrij heeft
--  en zijn adres invult maakt er een aan; alles wat hij verder meestuurt hoort
--  dan leeg te blijven.
-- ---------------------------------------------------------------------------

create or replace function public.eigen_rij_alleen_adres()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  /* De server (serverfuncties met de servicesleutel) heeft geen my_id() en
     mag alles. Zelfde regel als lezing_blijft_lezing. */
  if public.my_id() is null then return new; end if;

  /* Personeelszaken mag alles wat de policy toelaat. */
  if public.mag_dossiers_beheren() then return new; end if;

  /* Blijft over: je eigen rij. Dan alleen het adres. */
  if tg_op = 'INSERT' then
    new.birth_date        := null;
    new.birth_place       := null;
    new.nationality       := null;
    new.document_type     := null;
    new.document_number   := null;
    new.document_expires  := null;
    new.document_verified := false;
    new.bsn               := null;
    new.emergency_name    := null;
    new.emergency_phone   := null;
    new.emergency_relation := null;
    return new;
  end if;

  new.birth_date         := old.birth_date;
  new.birth_place        := old.birth_place;
  new.nationality        := old.nationality;
  new.document_type      := old.document_type;
  new.document_number    := old.document_number;
  new.document_expires   := old.document_expires;
  new.document_verified  := old.document_verified;
  new.bsn                := old.bsn;
  new.emergency_name     := old.emergency_name;
  new.emergency_phone    := old.emergency_phone;
  new.emergency_relation := old.emergency_relation;
  /* En je kunt je rij niet aan iemand anders hangen. */
  new.user_id            := old.user_id;
  return new;
end;
$$;

revoke execute on function public.eigen_rij_alleen_adres() from public, anon, authenticated;

drop trigger if exists eigen_rij_alleen_adres_trg on public.personnel_private;
create trigger eigen_rij_alleen_adres_trg
  before insert or update on public.personnel_private
  for each row execute function public.eigen_rij_alleen_adres();

comment on function public.eigen_rij_alleen_adres() is
  'Wie zijn eigen dossierrij schrijft en geen personeelszaken is, mag alleen address, postcode en city zetten. De rest wordt teruggezet op de oude waarde -- RLS werkt per rij, niet per kolom.';

-- --- ingeschreven door scripts/migratie-stand.cjs ---
do $stand$ begin
  if to_regprocedure('public.migratie_gedaan(integer,text)') is not null then
    perform public.migratie_gedaan(74, 'Je eigen woonadres invullen');
  end if;
end $stand$;

-- ===========================================================================
--  Klanten beheren
--
--  Casper: "Daarnaast moet je alle klanten, gebruikers ect kunnen beheren bij
--  managment, kunnen aanmaken."
--
--  Het beheerscherm zelf is app-werk; deze migratie is wat er in de database
--  moet staan vóórdat zo'n scherm veilig kan bestaan.
--
--  Waarom hij het niet kon vinden
--  ------------------------------
--
--  Drie dingen heten "Klant". public.companies is het factuuradres, een
--  Werkgever is het transportbedrijf waarvan de chauffeurs komen wassen, en de
--  rol customer is het inlogaccount dat aan een company hangt. Het menu-item
--  "Klanten" opent het werkgeversscherm. Een scherm voor companies bestond
--  niet -- en er is in de hele app ook geen enkele schrijfactie op die tabel.
--
--  companies_write staat al open voor het management, dus de database kon het
--  al. Wat eraan ontbrak zijn de twee dingen hieronder.
--
--  1. Een verwijdering die zichzelf meldt
--  --------------------------------------
--
--  0038 maakte meld_verwijdering() zodat een gewiste rij op elk apparaat
--  verdwijnt. Die trigger staat op notifications en signups, en verder
--  nergens. Gooi je nu een klant weg, dan blijft hij op elke telefoon en elke
--  laptop in de plaatselijke kopie staan -- de opruimmachinerie werkt wel,
--  maar krijgt niets te horen.
--
--  2. Een verwijdering die niet stil mislukt
--  -----------------------------------------
--
--  wash_jobs.company_id is on delete restrict (0001:75). Een klant met ook maar
--  één wasbeurt kan Postgres dus niet verwijderen; je krijgt foutcode 23001 met
--  een tekst over een vreemde sleutel. Dat is goed -- die wasbeurten zijn
--  omzet -- maar het is geen zin die je aan iemand kunt laten zien.
--
--  Erger is wat er NIET tegengehouden wordt: verkoopfactuur.company_id
--  (0064:83) en company_exact.company_id (0063:87) wijzen naar een klant maar
--  hebben helemaal geen vreemde sleutel. Gooi je die klant weg, dan blijven
--  zijn verkoopfacturen en zijn Exact-koppeling achter en wijzen ze naar een
--  bedrijf dat niet meer bestaat. Niets houdt dat tegen en niets meldt het.
--
--  Er komt geen vreemde sleutel bij: die zou nu al bestaande wezen weigeren en
--  daarmee de migratie laten omvallen op gegevens die er nu eenmaal zijn. In
--  plaats daarvan een trigger die vóór het verwijderen kijkt en met een leesbare
--  zin weigert.
--
--  Opnieuw draaien mag.
-- ===========================================================================

-- ---------------------------------------------------------------------------
--  1. Wat houdt het verwijderen van deze klant tegen?
--
--  Als functie, zodat het scherm het kan vragen VOORDAT iemand op verwijderen
--  drukt. Een knop die pas bij het indrukken vertelt dat het niet kan, is een
--  knop die je twee keer moet uitleggen.
-- ---------------------------------------------------------------------------

create or replace function public.klant_verwijderen_belet(klant_in text)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  wasbeurten integer;
  facturen   integer;
  mensen     integer;
begin
  select count(*) into wasbeurten from public.wash_jobs   where company_id = klant_in;
  select count(*) into facturen   from public.verkoopfactuur where company_id = klant_in;
  select count(*) into mensen     from public.profiles    where company_id = klant_in;

  if wasbeurten > 0 then
    return 'Er staan ' || wasbeurten || ' wasbeurten op deze klant. Die zijn omzet '
        || 'en blijven bewaard, dus de klant kan niet weg.';
  end if;

  if facturen > 0 then
    return 'Er liggen ' || facturen || ' verkoopfacturen op deze klant. Een factuur '
        || 'zonder klant is een factuur die niemand meer kan thuisbrengen.';
  end if;

  /*
   * Profielen worden bij een verwijdering op null gezet (0001:66), dus
   * Postgres houdt dit niet tegen. Wel het melden waard: die mensen raken
   * daarmee hun klantenportaal kwijt.
   */
  if mensen > 0 then
    return 'Er hangen ' || mensen || ' inlogaccounts aan deze klant. Haal die er '
        || 'eerst af, anders komen ze nergens meer binnen.';
  end if;

  return null;
end $$;

revoke execute on function public.klant_verwijderen_belet(text) from public, anon;
grant  execute on function public.klant_verwijderen_belet(text) to authenticated, service_role;

comment on function public.klant_verwijderen_belet(text) is
  'Leeg als deze klant weg mag; anders een zin die zegt waarom niet. Bedoeld om te tonen voordat iemand op verwijderen drukt.';

-- ---------------------------------------------------------------------------
--  2. En dezelfde vraag als slot, vlak voor het verwijderen
--
--  Niet alleen in het scherm. Een verwijdering kan ook via de wachtrij van een
--  ander apparaat binnenkomen, of met de hand in de SQL-editor.
-- ---------------------------------------------------------------------------

create or replace function public.klant_niet_zomaar_weg()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare reden text;
begin
  reden := public.klant_verwijderen_belet(old.id);
  if reden is not null then
    raise exception '%', reden using errcode = 'restrict_violation';
  end if;
  return old;
end $$;

revoke execute on function public.klant_niet_zomaar_weg() from public, anon, authenticated;

drop trigger if exists klant_niet_zomaar_weg_trg on public.companies;
create trigger klant_niet_zomaar_weg_trg
  before delete on public.companies
  for each row execute function public.klant_niet_zomaar_weg();

-- ---------------------------------------------------------------------------
--  3. En als hij dan weg mag: het melden
--
--  meld_verwijdering() bestaat sinds 0038 en stond op twee tabellen. Voor
--  companies werkt hij meteen: de tabelnaam in Postgres en de EntityName in de
--  app heten allebei 'companies'.
-- ---------------------------------------------------------------------------

drop trigger if exists companies_verwijderd on public.companies;
create trigger companies_verwijderd
  after delete on public.companies
  for each row execute function public.meld_verwijdering();

